@@ -690,8 +678,6 @@ export class MessageSend {
           serverURI.asciiHostPort
         );
       }
-      this.notifyListenerOnStopSending(null, exitCode, null, null);
-      this.fail(exitCode, errorMsg);
       return;
     }
